<?php require_once '../config/database.php'; require_once '../includes/auth.php'; if(empty($_SESSION['admin'])) json_response(false,'Admin login required.'); $data=json_decode(file_get_contents('php://input'),true) ?: $_POST; $status=$data['status']??''; $allowed=['Pending','Preparing','Out for Delivery','Delivered','Cancelled']; if(!in_array($status,$allowed,true))json_response(false,'Invalid order status.');$stmt=$pdo->prepare('UPDATE orders SET order_status=? WHERE id=?');$stmt->execute([$status,(int)($data['order_id']??0)]);json_response(true,'Order status updated.'); ?>